import json

from dojo_support import fail, say
from words import top_k, word_count


def show(o):
    return json.dumps(o, ensure_ascii=False)


def why(got, default):
    """What is actually wrong with a result, so the hint matches the mistake rather than the test's name."""
    ks = list(got)
    if "" in ks:
        return "empty"
    if any(k != k.lower() for k in ks):
        return "case"
    if any(not k.isalnum() for k in ks):
        return "punctuation"
    return default


def test_lv2_order():
    got, want = [list(x) for x in top_k({"a": 1, "b": 3, "c": 2}, 3)], [["b", 3], ["c", 2], ["a", 1]]
    if got != want:
        fail("wrong_order", say(f"top_k({{a:1, b:3, c:2}}, 3) 应该是 {show(want)}，实际是 {show(got)}。", f"top_k({{a:1, b:3, c:2}}, 3) should be {show(want)}, got {show(got)}."))


def test_lv2_ties():
    got, want = [list(x) for x in top_k({"pear": 2, "apple": 2, "fig": 5, "kiwi": 1}, 3)], [["fig", 5], ["apple", 2], ["pear", 2]]
    if len(got) > 3:
        fail("too_many", say(f"k = 3 时返回了 {len(got)} 个：{show(got)}。", f"With k = 3 it returned {len(got)}: {show(got)}."))
    if got != want:
        fail("tie_order", say(f"次数相同的 apple 和 pear 要按字母顺序：期望 {show(want)}，实际 {show(got)}。", f"apple and pear have the same count and must be alphabetical: expected {show(want)}, got {show(got)}."))


def test_lv2_k():
    counts = {"a": 3, "b": 2, "c": 1}
    two = [list(x) for x in top_k(counts, 2)]
    if len(two) > 2:
        fail("too_many", say(f"k = 2 时返回了 {len(two)} 个：{show(two)}。", f"With k = 2 it returned {len(two)}: {show(two)}."))
    every = top_k(counts, 10)
    if len(every) != 3:
        fail("too_few", say(f"k = 10 而只有 3 个词时，应该返回全部 3 个，实际返回 {len(every)} 个。", f"With k = 10 and only 3 words, all 3 should come back; got {len(every)}."))
    if two != [["a", 3], ["b", 2]]:
        fail("wrong_order", say(f"k = 2 时应该是 [[\"a\",3],[\"b\",2]]，实际是 {show(two)}。", f"With k = 2 it should be [[\"a\",3],[\"b\",2]], got {show(two)}."))
